mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM (
SELECT 'BOARD' AS type, BNO AS targetNo, TO_CHAR(BNO) AS parentId, TITLE AS targetTitle, CONTENT AS content, REGDATE AS regdate FROM FREE_BOARD_TBL WHERE USER_ID = #{userId}
UNION ALL
SELECT 'REPLY' AS type, R.CNO AS targetNo, TO_CHAR(R.BNO) AS parentId, B.TITLE AS targetTitle, TO_CLOB(R.CONTENT) AS content, R.REGDATE AS regdate FROM FREE_COMMENT_TBL R JOIN FREE_BOARD_TBL B ON R.BNO = B.BNO WHERE R.USER_ID = #{userId}
UNION ALL
SELECT 'REVIEW' AS type, R.REVIEW_ID AS targetNo, R.SHOW_ID AS parentId, S.TITLE AS targetTitle, R.CONTENT AS content, R.CREATED_AT AS regdate FROM REVIEW_TBL R JOIN SHOW_TBL S ON R.SHOW_ID = S.SHOW_ID WHERE R.USER_ID = #{userId}
ORDER BY regdate DESC ) A WHERE ROWNUM <= #{endRow} ) WHERE RNUM >= #{startRow}

mapper.update:
UPDATE USER_TBL
   SET NICKNAME = #{nickname}
 WHERE USER_ID  = #{userId}

UPDATE PROFILE_TBL

  UPDATED_AT = SYSDATE,
  BIRTH_DATE = TO_DATE(#{birthDate}, 'YYYY-MM-DD'),
  BIO = #{bio}

WHERE USER_ID = #{userId}

UPDATE PROFILE_TBL
   SET PHOTO_URL  = #{photoUrl}
     , UPDATED_AT = SYSDATE
 WHERE USER_ID    = #{userId}
